<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/bootstrap.php'; require_once __DIR__ . '/../../app/read_queries.php'; require_once __DIR__ . '/../../app/operational_writes.php';$action=(string)($_GET['accion']??'registrar');if(!in_array($action,['registrar','resolver'],true)){http_response_code(404);exit('Acción no disponible.');}require_permission($action==='registrar'?'INCIDENCIAS_REGISTRAR':'INCIDENCIAS_RESOLVER');if($action==='registrar'){try{$solicitudes=operation_list('DECLARE @total_registros INT; EXEC dbo.sp_listar_solicitudes @buscar=NULL,@estado=NULL,@cliente_id=NULL,@desde=NULL,@hasta=NULL,@pagina=1,@por_pagina=100,@total_registros=@total_registros OUTPUT; SELECT @total_registros AS total_registros;');$types=read_procedure_sets('EXEC dbo.sp_listar_tipos_incidencia @solo_activos=1;', [])[0]??[];}catch(PDOException){read_error_response('No se pudieron cargar los datos del formulario.');}}else{$incident=filter_var($_GET['incidencia_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($incident===false){http_response_code(404);exit('Incidencia no encontrada.');}}
?>
<div class="modal is-active" role="dialog" aria-modal="true" aria-labelledby="titulo-incidencia"><div class="modal-background" data-close-modal></div><div class="modal-card"><header class="modal-card-head"><p class="modal-card-title" id="titulo-incidencia"><?= $action==='registrar'?'Registrar incidencia':'Resolver incidencia' ?></p><button class="modal-close icon-button" type="button" aria-label="Cerrar" data-close-modal><?= svg_icon('close') ?></button></header><form hx-post="/entregas/incidencia.php" hx-target="#mensaje-incidencia" hx-swap="innerHTML"><section class="modal-card-body"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="<?= e($action) ?>"><div id="mensaje-incidencia" role="alert"></div><?php if($action==='registrar'):?><div class="field"><label class="label" for="incidencia-solicitud">Solicitud</label><div class="select is-fullwidth"><select id="incidencia-solicitud" name="solicitud_id" required><option value="">Selecciona</option><?php foreach($solicitudes as $row):?><option value="<?= (int)$row['solicitud_id'] ?>"><?= e($row['codigo_solicitud'].' · '.$row['estado']) ?></option><?php endforeach;?></select></div></div><div class="field"><label class="label" for="incidencia-tipo">Tipo</label><div class="select is-fullwidth"><select id="incidencia-tipo" name="tipo_incidencia_id" required><option value="">Selecciona</option><?php foreach($types as $row):?><option value="<?= (int)$row['tipo_incidencia_id'] ?>"><?= e($row['nombre']) ?></option><?php endforeach;?></select></div></div><div class="field"><label class="label" for="incidencia-descripcion">Descripción</label><textarea class="textarea" id="incidencia-descripcion" name="descripcion" maxlength="500" required></textarea></div><?php else:?><input type="hidden" name="incidencia_id" value="<?= (int)$incident ?>"><div class="field"><label class="label" for="incidencia-resolucion">Resolución</label><textarea class="textarea" id="incidencia-resolucion" name="resolucion" maxlength="500" required autofocus></textarea></div><?php endif;?></section><footer class="modal-card-foot"><div class="buttons"><button class="button is-primary" type="submit"><?= $action==='registrar'?'Registrar':'Resolver' ?></button><button class="button button-secondary" type="button" data-close-modal>Cancelar</button></div></footer></form></div></div>
